UPDATE bank_soal SET description='Tumbuhan dengan nama ilmiah Polianthes tuberosa memiliki bunga putih berbentuk tabung yang tersusun pada tangkai panjang dan mengeluarkan aroma harum terutama pada malam hari. Dalam bahasa Indonesia, tumbuhan ini dikenal sebagai ...', options='[{"id": "019897ca-a591-71e5-afd5-16d9ad8aecd9", "description": "Melati", "isCorrect": false, "point": 1}, {"id": "019897ca-a591-786b-8b10-42219a6369dd", "description": "Mawar", "isCorrect": false, "point": 1}, {"id": "019897ca-a591-7ec8-bf51-c2e073071f89", "description": "Kenanga", "isCorrect": false, "point": 1}, {"id": "019897ca-a592-7af3-9d50-d22b11239e80", "description": "Cempaka", "isCorrect": false, "point": 1}, {"id": "019897ca-a593-75a7-97db-e687cb8d945a", "description": "Sedap malam", "isCorrect": true, "point": 1}]'::jsonb, explanation='DIKETAHUI:
- Nama ilmiah tumbuhan: Polianthes tuberosa.
