UPDATE bank_soal SET description='Siapakah presiden keempat Republik Indonesia?', options='[{"id": "019897c9-d5e0-7533-ac02-f5fcfe038bfc", "description": "Soeharto", "isCorrect": false, "point": 1}, {"id": "019897c9-d5e1-7121-8e5b-23c7b556a975", "description": "B.J. Habibie", "isCorrect": false, "point": 1}, {"id": "019897c9-d5e1-77c5-ba3a-98d35aaac8e4", "description": "Ir. Soekarno", "isCorrect": false, "point": 1}, {"id": "019897c9-d5e1-7e9c-936c-a70295f99022", "description": "Megawati Soekarnoputri", "isCorrect": false, "point": 1}, {"id": "019897c9-d5e2-7888-a2c2-2abf9170808b", "description": "Abdurrahman Wahid (Gus Dur)", "isCorrect": true, "point": 1}]'::jsonb, explanation='DIKETAHUI:
