UPDATE bank_soal SET description='Berdasarkan estimasi Perserikatan Bangsa-Bangsa, negara dengan jumlah penduduk terbanyak ketiga di dunia adalah ...', options='[{"id": "019897ca-a544-7591-8ec7-0cda3f89430e", "description": "Indonesia", "isCorrect": false, "point": 1}, {"id": "019897ca-a544-7db9-8fa1-2d975bd23533", "description": "Amerika Serikat", "isCorrect": true, "point": 1}, {"id": "019897ca-a545-7726-84b5-dffac07126a4", "description": "Rusia", "isCorrect": false, "point": 1}, {"id": "019897ca-a545-7db7-8a17-e3466cfede58", "description": "India", "isCorrect": false, "point": 1}, {"id": "019897ca-a546-7595-8162-31d8b678656c", "description": "Tiongkok", "isCorrect": false, "point": 1}]'::jsonb, explanation='DIKETAHUI:
