UPDATE bank_soal SET description='Selat yang memisahkan Pulau Kalimantan dan Pulau Sulawesi adalah ...', options='[{"id": "019897b3-f7c4-7510-8171-a53a5613c746", "description": "Selat Sunda", "isCorrect": false, "point": 1}, {"id": "019897b3-f7c5-7059-9f2b-c9efa2820595", "description": "Selat Karimata", "isCorrect": false, "point": 1}, {"id": "019897b3-f7c5-790a-be90-5408402cb5fb", "description": "Selat Lombok", "isCorrect": false, "point": 1}, {"id": "019897b3-f7c6-74d4-aa08-7af324186cc1", "description": "Selat Makassar", "isCorrect": true, "point": 1}, {"id": "019897b3-f7c7-70e3-a118-c7b8d28f79c0", "description": "Selat Malaka", "isCorrect": false, "point": 1}]'::jsonb, explanation='DIKETAHUI:
