UPDATE bank_soal SET description='Lengkapilah analogi berikut dengan rangkaian kata yang paling tepat. ... : KUNCI : ... = MENULIS : PULPEN : ...', options='[{"id": "0198657a-ad1d-794c-8ef5-c57c8593ec43", "description": "Pintu : Jari : Buku", "isCorrect": false, "point": 1}, {"id": "0198657a-ad1f-7dc0-8171-4fbfd299b55a", "description": "Membuka : Pintu : Kertas", "isCorrect": true, "point": 1}, {"id": "0198657a-ad21-7e11-9ff8-0bbd4581f23b", "description": "Memutar : Gerbang : Tinta", "isCorrect": false, "point": 1}, {"id": "0198657a-ad24-7961-8e77-39a1e4777fde", "description": "Mengetik : Kata : Pensil", "isCorrect": false, "point": 1}, {"id": "0198657a-ad26-7b83-b648-2a97eec7e5ce", "description": "Membuka : Gagang : Tinta", "isCorrect": false, "point": 1}]'::jsonb, explanation='DIKETAHUI:
